import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
const source = await readFile('apps/web/public/offline-guides.js', 'utf8');
const { guideCopy, savePublicGuides, readPublicGuides } = await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
const now = Date.now();
const guide = { id: 'guide', operadora: 'TIM', topico: 'chip-esim', titulo: '<script>unsafe</script>', resumo: 'Resumo', passos: ['Abra as configurações'], fonte: 'https://www.tim.com.br/ajuda', canalOficial: 'https://tim.com.br/ajuda', revisadoEm: new Date(now - 86400000).toISOString(), validoAte: new Date(now + 86400000).toISOString(), privateField: 'drop' };
const copy = guideCopy('fixture', Array.from({ length: 120 }, () => guide), now, now);
assert.equal(copy.guides.length, 100);
assert.equal(copy.guides[0].privateField, undefined);
for (const invalid of [{ ...guide, fonte: 'https://tim.com.br.evil.example' }, { ...guide, fonte: 'http://tim.com.br' }, { ...guide, passos: [] }, { ...guide, operadora: 'OTHER' }]) assert.throws(() => guideCopy('fixture', [invalid], now, now));
let raw = null;
const storage = { getItem() { return raw; }, setItem(_key, value) { raw = value; }, removeItem() { raw = null; } };
savePublicGuides('fixture', [guide], storage);
assert.equal(readPublicGuides(storage, now + 1000).guides.length, 1);
assert.equal(readPublicGuides(storage, now + 2 * 86400000).guides.length, 0);
assert.equal(readPublicGuides(storage, now + 49 * 3600000), null);
assert.equal(raw, null);
raw = 'x'.repeat(300001); assert.equal(readPublicGuides(storage, now), null);
console.log('Web offline guides: bounded public fields, official URLs, expiry and invalid copy passed.');
